#pragma once
inline nlohmann::json rendering111Proof(hb::gpu::Device& gpu,const std::string& fixture){
 using namespace hb::gpu;std::ifstream input(fixture);const auto packets=nlohmann::json::parse(input).at("rendering111");SceneRenderer r(gpu,64,64);SceneFrame frame;frame.clear={0,0,0,1};frame.eye={0,0,-1,0};frame.screenEffects.emplace();auto& s=*frame.screenEffects;s.path={1,2,1,0};s.pathQuality={1,0,0,0};s.camera={.1f,100,0,.043744f};s.eye=frame.eye;s.forward={0,0,1,0};s.geometry={0,20,1,4};s.geometryInfo={1,1,0,0};s.geometryLimits={256,.001f,0,0};s.transport={0,1,1,32};s.inverseVP=identity;s.inverseVP[0]=s.inverseVP[5]=11.43f;auto world=r.createDataTexture(1,1,std::vector<std::uint8_t>(16),4,true);r.setGeometryScene(&world);nlohmann::json proof;
 for(const std::string mode:{"raw","mip"}){const auto& p=packets.at(mode);const auto data=p.at("data").get<std::vector<float>>();std::vector<std::uint8_t> bytes(data.size()*4);std::memcpy(bytes.data(),data.data(),bytes.size());auto env=r.createDataTexture(p.at("width").get<UINT>(),p.at("height").get<UINT>(),bytes,4,true);s.pathMap={p.at("mipOffset").get<float>()>0?p.at("texels").get<float>():0,p.at("sourceWidth"),p.at("sourceHeight"),0};s.pathOptions={1,0,p.at("mipOffset"),0};r.setPathEnvironment(&env);r.begin(frame);const auto rgba=r.readPixels();double sum=0,sum2=0;for(int y=16;y<48;y++)for(int x=16;x<48;x++){double v=rgba[(y*64+x)*4];sum+=v;sum2+=v*v;}const double mean=sum/1024,variance=sum2/1024-mean*mean;proof[mode]={{"mean",mean},{"variance",variance}};if(mode=="mip"){const auto saved=s;for(int i=0;i<2;i++){s=saved;if(i==0)s.pathOptions[2]+=1;else s.pathMap[0]-=1;bool rejected=false;try{r.begin(frame);r.readPixels();}catch(const std::exception&){rejected=true;}assert(rejected);}s=saved;}r.setPathEnvironment(nullptr);}
 std::cerr<<"rendering111 diagnostics "<<proof.dump()<<std::endl;assert(proof["raw"]["variance"].get<double>()>100);assert(proof["mip"]["variance"].get<double>()<proof["raw"]["variance"].get<double>()*.8);assert(proof["mip"]["mean"].get<double>()>25&&proof["mip"]["mean"].get<double>()<240);frame.screenEffects.reset();r.setGeometryScene(nullptr);r.begin(frame);assert(r.bloomTextureBytes()==0);proof["passed"]=true;proof["hdrLOD"]=true;proof["legacyLayout"]=true;proof["invalidMipLayout"]=true;proof["disabledResourcesZero"]=true;return proof;
}
